                            imageVector = Icons.AutoMirrored.Filled.ArrowBack,
                            contentDescription = "Back"
                        )
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = MaterialTheme.colorScheme.primaryContainer,
                    titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer,
                )
            )
        }
    ) { innerPadding ->
        Box(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
        ) {
            val json = questionnaireJson
            if (json == null || isSaving) {
                CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
            } else {
                Questionnaire(
                    questionnaireJson = json,
                    config = QuestionnaireConfig(
                        showSubmitButton = true,
                        showCancelButton = true,
                        submitButtonText = "Save Visit",
                    ),
                    onSubmit = { getResponse ->
                        scope.launch {
                            try {
                                val response: QuestionnaireResponse = getResponse()
                                isSaving = true
                                viewModel.saveVisit(patientId, response)
                                onNavigateBack()
                            } catch (e: CancellationException) {
                                // Answer validation failed; the form is already showing the errors
                                isSaving = false
                            } catch (e: Exception) {
                                Log.e("RecordVisitScreen", "Failed to save visit", e)
                                isSaving = false
                            }
                        }
                    },
                    onCancel = onNavigateBack,
                )
            }
        }
    }
}

package com.example.ancapp

import android.os.Bundle
import androidx.activity.ComponentActivity
import androidx.activity.compose.setContent
import androidx.activity.viewModels
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.ui.Modifier
import androidx.navigation.NavType
import androidx.navigation.compose.NavHost
import androidx.navigation.compose.composable
import androidx.navigation.compose.rememberNavController
import androidx.navigation.navArgument
import com.example.ancapp.ui.AncViewModel
import com.example.ancapp.ui.PatientDetailScreen
import com.example.ancapp.ui.RecordVisitScreen
import com.example.ancapp.ui.RegisterScreen

class MainActivity : ComponentActivity() {

    private val viewModel: AncViewModel by viewModels()

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        setContent {
            MaterialTheme {
                Surface(modifier = Modifier.fillMaxSize()) {
                    val navController = rememberNavController()

                    NavHost(
                        navController = navController,
                        startDestination = "register"
                    ) {
                        composable("register") {
                            RegisterScreen(
                                viewModel = viewModel,
                                onPatientClick = { patientId ->
                                    navController.navigate("patient/$patientId")
                                }
                            )
                        }

                        composable(
                            route = "patient/{patientId}",
                            arguments = listOf(navArgument("patientId") { type = NavType.StringType })
                        ) { backStackEntry ->
                            val patientId = backStackEntry.arguments?.getString("patientId").orEmpty()
                            PatientDetailScreen(
                                patientId = patientId,
                                viewModel = viewModel,
                                onBack = { navController.popBackStack() },
                                onRecordNewVisit = { id ->
                                    navController.navigate("newVisit/$id")
                                }
                            )
                        }

                        composable(
                            route = "newVisit/{patientId}",
                            arguments = listOf(navArgument("patientId") { type = NavType.StringType })
                        ) { backStackEntry ->
                            val patientId = backStackEntry.arguments?.getString("patientId").orEmpty()
                            RecordVisitScreen(
                                patientId = patientId,
                                viewModel = viewModel,
                                onNavigateBack = { navController.popBackStack() }
                            )
                        }
                    }
                }
            }
        }
    }
}

